const float PI = 3.141592;

void mainImage( out vec4 fragColor, in vec2 c )
{

    float shrink = 4.;
    float aspect = iResolution.x/iResolution.y;
    float scale = min(iResolution.x,iResolution.y)/shrink;
    vec2 offset = ((aspect >1.)?vec2(aspect*shrink/2.,shrink/2.):vec2(shrink/2.,shrink/2./aspect));
    vec2 uv = c/scale - offset;
    float r = 1.;
    float e = 0.01;

    float inside = 1.0;
    vec3 col;

    uv+=vec2(sin(iTime),.0);

    if (uv.x<-11110.) {
        if (abs(uv.x)<r && abs(uv.y)<r) inside= 0.;
        // if (abs(r-abs(uv.x)) + abs(r-abs(uv.y))<e) inside=1.0;
        //inside=uv.x/offset.x+uv.y/offset.y;
    } else {
        //if (uv.x*uv.x+uv.y*uv.y<r*r) inside= 0.;    
        float d=(uv.x*uv.x+uv.y*uv.y);
        if (r>d) inside=d;
        else inside=2.*r-d;
    }
    inside*=(sin(iTime/2.)+1.5)/2.5;

    float t=inside*(cos(uv.x*PI/2.)+1.)/2.;


    col=vec3(inside,inside,inside);



    fragColor = vec4(col,1.0);
}
